(function(root){"use strict";const rows=[{"id": "generator-sharing", "fn": "generator-sharing", "title": "Generator synchronisation & load sharing", "chapter": 6, "description": "Explore phase slip, active-power droop and reactive-power sharing.", "fields": [{"key": "frequency", "label": "Nominal bus frequency", "unit": "Hz", "value": 50, "min": 40, "max": 70}, {"key": "slip", "label": "Incoming frequency minus bus frequency", "unit": "Hz", "value": 0.1, "min": -2, "max": 2}, {"key": "phase", "label": "Initial phase difference", "unit": "°", "value": 20, "min": -180, "max": 180}, {"key": "voltage", "label": "Bus line voltage", "unit": "V", "value": 440, "min": 100, "max": 15000}, {"key": "incoming", "label": "Incoming line voltage", "unit": "V", "value": 450, "min": 100, "max": 15000}, {"key": "rating1", "label": "Generator 1 active rating", "unit": "kW", "value": 1000, "min": 1, "max": 20000}, {"key": "rating2", "label": "Generator 2 active rating", "unit": "kW", "value": 1000, "min": 1, "max": 20000}, {"key": "droop1", "label": "Generator 1 speed droop", "unit": "%", "value": 4, "min": 0.5, "max": 10}, {"key": "droop2", "label": "Generator 2 speed droop", "unit": "%", "value": 4, "min": 0.5, "max": 10}, {"key": "load", "label": "Active load", "unit": "kW", "value": 1000, "min": 0, "max": 40000}, {"key": "reactive", "label": "Reactive load", "unit": "kvar", "value": 400, "min": -20000, "max": 20000}, {"key": "qbase1", "label": "Generator 1 reactive base", "unit": "kvar", "value": 600, "min": 1, "max": 20000}, {"key": "qbase2", "label": "Generator 2 reactive base", "unit": "kvar", "value": 600, "min": 1, "max": 20000}, {"key": "qdrop1", "label": "Generator 1 voltage droop", "unit": "%", "value": 4, "min": 0.5, "max": 10}, {"key": "qdrop2", "label": "Generator 2 voltage droop", "unit": "%", "value": 4, "min": 0.5, "max": 10}, {"key": "level", "label": "Applied question", "value": "1", "options": [["1", "1 · Foundation"], ["2", "2 · Applied"], ["3", "3 · Advanced"]]}], "notes": ["Phase(t) = phase(0) + 360 Δf t. The incoming machine is a separate synchronisation demonstration; load sharing describes two already connected generators.", "P1/P2 = (rating1/droop1)/(rating2/droop2), with equal no-load frequency references. Q uses the analogous linear voltage-droop model with equal voltage references.", "Voltage inputs are line RMS; the waveform display slows the common base to 1 Hz while retaining the entered frequency difference. No breaker closing, transient current, excitation limits or capability curve is simulated. Entered ratings are comparison bases, not an operational approval."]}, {"id": "blackout", "fn": "blackout", "title": "Power balance & generator loss", "chapter": 8, "description": "Trip one generator, shed discretionary load and inspect reserve and frequency response.", "fields": [{"key": "capacity", "label": "Surviving generator capacity", "unit": "kW", "value": 1000, "min": 1, "max": 20000}, {"key": "lost", "label": "Initial lost-generator output", "unit": "kW", "value": 400, "min": 0, "max": 20000}, {"key": "essential", "label": "Essential demand", "unit": "kW", "value": 500, "min": 0, "max": 20000}, {"key": "optional", "label": "Discretionary demand", "unit": "kW", "value": 400, "min": 0, "max": 20000}, {"key": "shed", "label": "Discretionary load to shed", "unit": "kW", "value": 300, "min": 0, "max": 20000}, {"key": "delay", "label": "Shedding delay after trip", "unit": "s", "value": 1, "min": 0, "max": 20}, {"key": "tau", "label": "Governor response time constant", "unit": "s", "value": 2, "min": 0.2, "max": 20}, {"key": "inertia", "label": "Aggregate inertia constant on surviving base", "unit": "s", "value": 5, "min": 0.5, "max": 20}, {"key": "frequency", "label": "Initial frequency", "unit": "Hz", "value": 50, "min": 40, "max": 70}, {"key": "level", "label": "Applied question", "value": "1", "options": [["1", "1 · Foundation"], ["2", "2 · Applied"], ["3", "3 · Advanced"]]}], "notes": ["At t=0 the second generator trips. Before the trip, total demand is supplied; the surviving output starts at demand minus lost output.", "dP/dt = (min(demand, capacity) − P)/τ; df/dt = f0(P − demand)/(2 H capacity). Exact integration is used between switching events.", "Undamped short-time swing approximation: frequency restoration, voltage collapse, protection and automatic restart are excluded. This is a disturbance experiment, not a blackout recovery procedure."]}, {"id": "thruster-allocation", "fn": "thruster-allocation", "title": "Thruster force & moment allocation", "chapter": 13, "description": "Balance surge, sway and yaw with three fixed-direction thrusters, including failures and force limits.", "fields": [{"key": "surge", "label": "Required surge force", "unit": "kN", "value": 100, "min": -500, "max": 500}, {"key": "sway", "label": "Required sway force", "unit": "kN", "value": 80, "min": -500, "max": 500}, {"key": "yaw", "label": "Required yaw moment", "unit": "kN·m", "value": 0, "min": -20000, "max": 20000}, {"key": "beam", "label": "Spacing between stern thrusters", "unit": "m", "value": 16, "min": 1, "max": 80}, {"key": "bow", "label": "Bow thruster distance ahead of origin", "unit": "m", "value": 25, "min": 1, "max": 150}, {"key": "limit", "label": "Absolute force limit per thruster", "unit": "kN", "value": 200, "min": 1, "max": 1000}, {"key": "failure", "label": "Unavailable thruster", "value": "none", "options": [["none", "None"], ["port", "Port stern"], ["starboard", "Starboard stern"], ["bow", "Bow"]]}, {"key": "level", "label": "Applied question", "value": "1", "options": [["1", "1 · Foundation"], ["2", "2 · Applied"], ["3", "3 · Advanced"]]}], "notes": ["Axes: x forward, y port; positive yaw is counterclockwise. Port/starboard stern thrusters act along x at y=±beam/2; the bow thruster acts along y at x=bow.", "Fbow = Fy; Fport = Fx/2 − (Mz − bow·Fy)/beam; Fstarboard = Fx − Fport. Each command is then clipped or failed to zero.", "Fixed allocation followed by clipping, without reallocation. Residuals expose infeasible demand. No DP capability, positioning controller, hydrodynamic interaction or redundancy certification is implied."]}, {"id": "mooring-forces", "fn": "mooring-forces", "title": "Elastic mooring lines", "chapter": 3, "description": "Move the vessel sideways and inspect four line tensions, restoring force and slack.", "fields": [{"key": "reach", "label": "Horizontal anchor distance from each fairlead", "unit": "m", "value": 30, "min": 1, "max": 300}, {"key": "offset", "label": "Longitudinal anchor offset", "unit": "m", "value": 20, "min": 0, "max": 300}, {"key": "pretension", "label": "Initial tension per line", "unit": "kN", "value": 50, "min": 0, "max": 1000}, {"key": "ea", "label": "Axial stiffness EA", "unit": "kN", "value": 20000, "min": 1, "max": 1000000}, {"key": "displacement", "label": "Prescribed port displacement", "unit": "m", "value": 1, "min": -20, "max": 20}, {"key": "allowable", "label": "Entered allowable tension", "unit": "kN", "value": 400, "min": 1, "max": 10000}, {"key": "level", "label": "Applied question", "value": "1", "options": [["1", "1 · Foundation"], ["2", "2 · Applied"], ["3", "3 · Advanced"]]}], "notes": ["Four horizontal, massless, straight lines: two anchors on either side, with equal ±longitudinal offsets. Only sideways translation is allowed.", "L0 = Linitial/(1 + Tinitial/EA); T = max(0, EA(L/L0 − 1)). Sum the transverse components at the displaced fairleads.", "Utilisation uses your entered allowable tension. Catenary, water depth, fenders, dynamics and rope-specific nonlinear stiffness are excluded."]}, {"id": "flooding", "fn": "flooding", "title": "Connected compartment flooding", "chapter": 14, "description": "Follow ingress, transfer and pump-out in two compartments, with a water-volume balance.", "fields": [{"key": "area1", "label": "Compartment 1 plan area", "unit": "m²", "value": 30, "min": 1, "max": 500}, {"key": "area2", "label": "Compartment 2 plan area", "unit": "m²", "value": 25, "min": 1, "max": 500}, {"key": "permeability", "label": "Common floodable volume fraction", "unit": "", "value": 0.9, "min": 0.1, "max": 1}, {"key": "sea", "label": "Sea level above compartment base", "unit": "m", "value": 3, "min": 0.1, "max": 10}, {"key": "initial1", "label": "Initial level in compartment 1", "unit": "m", "value": 0, "min": 0, "max": 10}, {"key": "initial2", "label": "Initial level in compartment 2", "unit": "m", "value": 0, "min": 0, "max": 10}, {"key": "breach", "label": "Sea opening area at base", "unit": "m²", "value": 0.02, "min": 0, "max": 0.2}, {"key": "connection", "label": "Open inter-compartment area at base", "unit": "m²", "value": 0.01, "min": 0, "max": 0.2}, {"key": "cd", "label": "Discharge coefficient", "unit": "", "value": 0.62, "min": 0.1, "max": 1}, {"key": "pump", "label": "Pump-out from compartment 2", "unit": "m³/h", "value": 10, "min": 0, "max": 500}, {"key": "duration", "label": "Simulated duration", "unit": "min", "value": 10, "min": 0.1, "max": 30}, {"key": "level", "label": "Applied question", "value": "1", "options": [["1", "1 · Foundation"], ["2", "2 · Applied"], ["3", "3 · Advanced"]]}], "notes": ["Q = Cd A sign(Δh) sqrt(2g|Δh|). Both openings are at the common base. Liquid is incompressible and air is freely vented.", "Conservative 0.05 s substeps limit each transfer to the available donor volume and equalisation volume; pumping cannot remove absent water.", "Fixed hull and fixed sea level, compartments extend above every entered water level. Free-surface moments, trapped air, vessel sinkage and damaged stability are excluded."]}, {"id": "separator", "fn": "separator", "title": "Centrifugal separator", "chapter": 11, "description": "Compare centrifugal Stokes migration time with the available residence time.", "fields": [{"key": "rpm", "label": "Bowl speed", "unit": "rpm", "value": 6000, "min": 100, "max": 15000}, {"key": "diameter", "label": "Particle diameter", "unit": "µm", "value": 2, "min": 0.1, "max": 100}, {"key": "particleDensity", "label": "Particle density", "unit": "kg/m³", "value": 1000, "min": 500, "max": 10000}, {"key": "liquidDensity", "label": "Liquid density", "unit": "kg/m³", "value": 850, "min": 500, "max": 2000}, {"key": "viscosity", "label": "Dynamic viscosity at operating temperature", "unit": "mPa·s", "value": 20, "min": 0.5, "max": 1000}, {"key": "inner", "label": "Initial radius", "unit": "m", "value": 0.05, "min": 0.005, "max": 0.5}, {"key": "outer", "label": "Collection radius", "unit": "m", "value": 0.1, "min": 0.006, "max": 1}, {"key": "volume", "label": "Active liquid volume", "unit": "L", "value": 10, "min": 0.1, "max": 1000}, {"key": "flow", "label": "Throughput", "unit": "L/h", "value": 1000, "min": 1, "max": 100000}, {"key": "level", "label": "Applied question", "value": "1", "options": [["1", "1 · Foundation"], ["2", "2 · Applied"], ["3", "3 · Advanced"]]}], "notes": ["For a denser spherical particle, dr/dt = k r, k = d²(ρparticle − ρliquid)ω²/(18μ). Time to collection is ln(router/rinner)/k.", "Residence time = active liquid volume / throughput. The ideal trajectory is stopped at the collection radius.", "Dilute, isolated spheres in creeping flow. Particle Reynolds number is reported; values above 0.1 flag a weak Stokes assumption. Disc geometry, emulsions and real separation efficiency are excluded."]}, {"id": "freshwater", "fn": "freshwater", "title": "Vacuum freshwater generator", "chapter": 10, "description": "Balance feed heating, evaporation and condensation using local IAPWS-IF97 water properties.", "fields": [{"key": "pressure", "label": "Evaporator absolute pressure", "unit": "bar(a)", "value": 0.1, "min": 0.01, "max": 1}, {"key": "heat", "label": "Available heater duty", "unit": "kW", "value": 150, "min": 0, "max": 5000}, {"key": "feed", "label": "Feedwater mass flow", "unit": "kg/h", "value": 1000, "min": 1, "max": 50000}, {"key": "feedTemperature", "label": "Feedwater temperature", "unit": "°C", "value": 20, "min": 0, "max": 90}, {"key": "condenser", "label": "Available condenser duty", "unit": "kW", "value": 120, "min": 0, "max": 5000}, {"key": "salinity", "label": "Feed salt mass fraction", "unit": "%", "value": 3.5, "min": 0, "max": 10}, {"key": "level", "label": "Applied question", "value": "1", "options": [["1", "1 · Foundation"], ["2", "2 · Applied"], ["3", "3 · Advanced"]]}], "notes": ["Saturation temperature and latent heat use IAPWS-IF97 at the entered absolute pressure. Feed is heated with cp = 4.18 kJ/(kg·K).", "Distillate is limited by net evaporator heat, condenser duty and fresh water in the feed. Salt remains in the brine; evaporation stops before a brine salt mass fraction above 25%.", "Ideal steady balance with no heat loss or salt carryover. Boiling-point elevation and seawater property corrections are excluded; this is not a potable-water quality model."]}, {"id": "starting-air", "fn": "starting-air", "title": "Starting-air receiver", "chapter": 9, "description": "Inspect receiver pressure with compressor hysteresis, leakage and a timed air draw.", "fields": [{"key": "volume", "label": "Receiver volume", "unit": "m³", "value": 2, "min": 0.1, "max": 50}, {"key": "initial", "label": "Initial gauge pressure", "unit": "bar(g)", "value": 25, "min": 0, "max": 40}, {"key": "on", "label": "Compressor cut-in gauge pressure", "unit": "bar(g)", "value": 20, "min": 0, "max": 39}, {"key": "off", "label": "Compressor cut-out gauge pressure", "unit": "bar(g)", "value": 30, "min": 1, "max": 40}, {"key": "fad", "label": "Compressor free-air delivery", "unit": "m³/min", "value": 1, "min": 0, "max": 50}, {"key": "leak", "label": "Leakage as free air", "unit": "m³/min", "value": 0.05, "min": 0, "max": 10}, {"key": "draw", "label": "Timed draw as free-air volume", "unit": "m³", "value": 5, "min": 0, "max": 100}, {"key": "event", "label": "Draw time", "unit": "s", "value": 60, "min": 0, "max": 599}, {"key": "temperature", "label": "Constant receiver temperature", "unit": "°C", "value": 30, "min": 0, "max": 100}, {"key": "reference", "label": "Free-air reference temperature", "unit": "°C", "value": 20, "min": 0, "max": 50}, {"key": "level", "label": "Applied question", "value": "1", "options": [["1", "1 · Foundation"], ["2", "2 · Applied"], ["3", "3 · Advanced"]]}], "notes": ["Ideal gas, isothermal receiver. Free-air delivery and withdrawal refer to 1.01325 bar absolute and the entered reference temperature. Absolute pressure = gauge + 1.01325 bar.", "dp/dt = pref (Treceiver/Treference)(FAD − leakage)/V, with flows in m³/s. A 0.1 s event-aligned integration applies thermostat-style hysteresis.", "The timed draw is limited to free air available above atmospheric pressure; unmet draw is reported. Cooling, compressor power and engine-specific starting requirements are excluded."]}];root.MT_EDUCATION_MODEL_SCHEMAS=Object.fromEntries(rows.map(s=>[s.id,s]));})(typeof window==="undefined"?globalThis:window);
